// Cache entry metadata
struct CacheEntryHeader {
    uint32_t magic;
    uint32_t content_length;
    uint32_t header_length;
    uint32_t flags;
    char etag[64];
};

class MemoryPool {
private:
    std::vector<uint8_t> pool_;
    size_t offset_;
    std::mutex mtx_;

public:
    MemoryPool(size_t initial_size) : pool_(initial_size, 0), offset_(0) {}

    uint8_t* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (offset_ + size > pool_.size()) {
            pool_.resize(pool_.size() * 2 + size);
        }
        uint8_t* ptr = pool_.data() + offset_;
        offset_ += size;
        return ptr;
    }

    void reset() {
        std::lock_guard<std::mutex> lock(mtx_);
        offset_ = 0;
    }

    size_t used() const { return offset_; }
    size_t capacity() const { return pool_.size(); }
};

class HttpResponseCache {
private:
    MemoryPool pool_;
    std::unordered_map<std::string, size_t> index_;
    std::mutex index_mtx_;
    static constexpr uint32_t CACHE_MAGIC = 0xCAFEBABE;
    static constexpr size_t MAX_POOL_SIZE = 512 * 1024 * 1024; // 512MB

    // Compute total allocation size for a cache entry
    // header_data and content are stored contiguously
    uint32_t compute_entry_size(uint32_t header_len, uint32_t content_len) {
        // Total = sizeof(CacheEntryHeader) + header_len + content_len
        uint32_t metadata_size = static_cast<uint32_t>(sizeof(CacheEntryHeader));
        uint32_t total = metadata_size + header_len + content_len;
        return total;
    }

public:
    HttpResponseCache() : pool_(64 * 1024 * 1024) {} // 64MB initial

    bool store(const std::string& url,
              const std::string& response_headers,
              const std::vector<uint8_t>& content,
              const std::string& etag) {

        uint32_t header_len = static_cast<uint32_t>(response_headers.size());
        uint32_t content_len = static_cast<uint32_t>(content.size());

        // Validate individual sizes fit in uint32
        if (response_headers.size() > UINT32_MAX || content.size() > UINT32_MAX) {
            return false;
        }

        // Check pool capacity
        if (pool_.used() > MAX_POOL_SIZE) {
            return false;
        }

        // Compute total entry size
        uint32_t entry_size = compute_entry_size(header_len, content_len);

        // Sanity check: entry shouldn't be unreasonably small
        // (this catches the case where entry_size wrapped to near-zero)
        if (entry_size < sizeof(CacheEntryHeader)) {
            return false;
        }

        // Allocate from pool - entry_size is uint32_t, implicitly widened to size_t
        uint8_t* entry_ptr = pool_.allocate(static_cast<size_t>(entry_size));

        // Write header
        CacheEntryHeader* hdr = reinterpret_cast<CacheEntryHeader*>(entry_ptr);
        hdr->magic = CACHE_MAGIC;
        hdr->content_length = content_len;
        hdr->header_length = header_len;
        hdr->flags = 0;
        std::memset(hdr->etag, 0, sizeof(hdr->etag));
        std::memcpy(hdr->etag, etag.c_str(),
                    std::min(etag.size(), sizeof(hdr->etag) - 1));

        // Write response headers after metadata
        uint8_t* headers_dst = entry_ptr + sizeof(CacheEntryHeader);
        std::memcpy(headers_dst, response_headers.data(), header_len);

        // Write content after headers
        uint8_t* content_dst = headers_dst + header_len;
        std::memcpy(content_dst, content.data(), content_len);

        // Index the entry
        {
            std::lock_guard<std::mutex> lock(index_mtx_);
            index_[url] = entry_ptr - pool_.allocate(0) + pool_.used();
        }

        return true;
    }

    bool retrieve(const std::string& url, std::string& out_headers,
                  std::vector<uint8_t>& out_content) {
        std::lock_guard<std::mutex> lock(index_mtx_);
        auto it = index_.find(url);
        if (it == index_.end()) return false;
        // Retrieval logic omitted for brevity
        return true;
    }
};

// Proxy server that caches upstream responses
class CachingProxy {
private:
    HttpResponseCache cache_;
    std::string upstream_host_;
    uint16_t upstream_port_;

    // Simulate fetching from upstream
    bool fetch_upstream(const std::string& path,
                       std::string& resp_headers,
                       std::vector<uint8_t>& resp_body) {
        // In production this would make an HTTP request
        // For demonstration, read from local filesystem
        std::string safe_path = "/var/cache/proxy" + path;

        // Path validation - prevent traversal
        std::string canonical = safe_path;
        // Remove .. sequences
        while (canonical.find("..") != std::string::npos) {
            return false;
        }

        std::ifstream file(safe_path, std::ios::binary);
        if (!file) return false;

        file.seekg(0, std::ios::end);
        auto size = file.tellg();
        file.seekg(0, std::ios::beg);

        if (size < 0 || static_cast<uint64_t>(size) > 4ULL * 1024 * 1024 * 1024) {
            return false; // Reject files > 4GB
        }

        resp_body.resize(static_cast<size_t>(size));
        file.read(reinterpret_cast<char*>(resp_body.data()), size);

        resp_headers = "HTTP/1.1 200 OK\r\nContent-Length: " +
                      std::to_string(size) + "\r\n\r\n";
        return true;
    }

public:
    CachingProxy(const std::string& host, uint16_t port)
        : upstream_host_(host), upstream_port_(port) {}

    bool handle_request(const std::string& path) {
        std::string headers;
        std::vector<uint8_t> body;

        if (!fetch_upstream(path, headers, body)) {
            return false;
        }

        // Generate etag from content size
        std::string etag = "\"" + std::to_string(body.size()) + "\"";

        // Cache the response
        return cache_.store(path, headers, body, etag);
    }
};

int main() {
    CachingProxy proxy("backend.internal", 8080);
    // Handle incoming requests
    proxy.handle_request("/large-asset.bin");
    return 0;
}
